select case when s.rating >= 3.6 then 'high' when s.rating >= 2.5 then 'mid' else 'low' end as rating_bucket, round(stddev(oi.quantity), 2) as stddev_quantity, avg(oi.unit_price) as avg_unit_price from order_items oi inner join products p on oi.product_id = p.id inner join suppliers s on s.id = p.supplier_id group by case when s.rating >= 3.6 then 'high' when s.rating >= 2.5 then 'mid' else 'low' end having avg(oi.unit_price) > 330
